<template>
  <section class="contest-page">
    <div v-if="detail" class="contest-shell">
      <header class="contest-header">
        <button class="back-link" type="button" @click="goBack">返回团队比赛</button>
        <div class="contest-title-row"><div><span class="eyebrow">TEAM CONTEST</span><h1>{{ detail.contest.title }}</h1><p>{{ detail.team.name }}</p></div><div class="contest-stats"><article><span>赛制</span><strong>{{ scoringLabel(detail.contest.scoring_rule) }}</strong></article><article><span>状态</span><strong>{{ statusLabel(detail.contest.status) }}</strong></article></div></div>
        <nav class="contest-nav" aria-label="比赛导航">
          <router-link :to="`/contest/${contestID}/description`">比赛说明</router-link>
          <router-link :to="`/contest/${contestID}/problems`">题目列表</router-link>
          <router-link v-if="detail.contest.scoring_rule !== 'oi'" :to="`/contest/${contestID}/scoreboard`">排行榜</router-link>
        </nav>
      </header>

      <main class="contest-content">
        <template v-if="section === 'description'">
          <div class="two-column">
            <section class="panel description-panel"><div class="section-heading"><h2>比赛说明</h2><div v-if="detail.can_edit"><el-button v-if="detail.can_publish" type="success" :loading="publishing" @click="publishContest">发布比赛</el-button><el-button @click="editVisible=true">编辑设置</el-button><el-button @click="addVisible=true">添加题目</el-button></div></div><div class="description-copy">{{ detail.contest.description || '本场比赛暂未填写说明。' }}</div></section>
            <aside class="panel meta-panel"><h3>比赛信息</h3><dl><div><dt>开始时间</dt><dd>{{ dateText(detail.contest.starts_at) }}</dd></div><div><dt>结束时间</dt><dd>{{ dateText(detail.contest.ends_at) }}</dd></div><div><dt>比赛时长</dt><dd>{{ detail.contest.duration_minutes }} 分钟</dd></div><div><dt>计分规则</dt><dd>{{ scoringDescription(detail.contest.scoring_rule) }}</dd></div><div><dt>封榜</dt><dd>{{ detail.contest.freeze_enabled ? `结束前 ${detail.contest.freeze_duration_minutes} 分钟` : '未启用' }}</dd></div></dl></aside>
          </div>
        </template>

        <template v-else-if="section === 'problems'">
          <section class="panel problem-list-panel">
            <div class="section-heading"><div><h2>题目列表</h2><p>{{ detail.problems.length }} 道题 · 点击题目进入比赛模式题面</p></div><el-button v-if="detail.can_edit" type="primary" @click="addVisible=true">添加题目</el-button></div>
            <div class="problem-table-wrap"><table class="problem-table"><thead><tr><th>题号</th><th>题目名称</th><th>满分</th><th>我的状态</th></tr></thead><tbody><tr v-for="link in detail.problems" :key="link.problem_id"><td><router-link :to="problemRoute(link)">{{ link.label }}</router-link></td><td><router-link :to="problemRoute(link)">{{ link.problem.title }}</router-link></td><td>100</td><td><el-tag :type="problemStatusType(link.submission_status)" effect="plain">{{ problemStatusLabel(link.submission_status) }}</el-tag></td></tr></tbody></table></div>
            <el-empty v-if="!detail.problems.length" description="比赛暂未添加题目" />
          </section>
        </template>

        <template v-else-if="section === 'problem'">
          <div v-if="selectedLink" class="problem-layout">
            <section class="panel statement-panel"><div class="problem-toolbar"><div><span>{{ selectedLink.label }}</span><strong>{{ selectedLink.problem.title }}</strong></div><el-button type="primary" :disabled="!detail.can_submit" @click="openSubmit">提交代码</el-button></div><ProblemStatementView embedded :problem="selectedLink.problem" :problem-number="selectedLink.label" :show-meta="false" :show-title="false" /></section>
            <aside class="problem-side"><section class="panel navigator"><h3>题目导航</h3><div><router-link v-for="link in detail.problems" :key="link.problem_id" :class="{active:link.problem_id===selectedLink.problem_id}" :to="problemRoute(link)">{{link.label}}</router-link></div></section><section class="panel records"><div class="section-heading"><h3>本题提交</h3><el-button link @click="loadRecords">刷新</el-button></div><article v-for="row in problemRecords" :key="row.id"><StatusBadge :status="row.status"/><span>{{ row.language }}</span><time>{{ shortTime(row.created_at) }}</time></article><el-empty v-if="!problemRecords.length" :image-size="54" description="暂无提交" /></section></aside>
          </div>
        </template>

        <template v-else>
          <section class="panel scoreboard-panel" v-loading="rankingLoading">
            <div class="section-heading"><div><h2>{{ scoringLabel(detail.contest.scoring_rule) }} 排行榜</h2><p>{{ ranking.rows?.length || 0 }} 名参赛者 · {{ ranking.problems?.length || 0 }} 道题</p></div><el-button @click="loadRanking">刷新</el-button></div>
            <el-alert v-if="ranking.frozen" title="排行榜已封榜" :description="`当前展示结束前 ${ranking.freeze_duration_minutes} 分钟的快照；比赛结束后自动公开。`" type="warning" :closable="false" show-icon />
            <div class="scoreboard-scroll"><table class="scoreboard"><thead><tr><th class="sticky rank-col">排名</th><th class="sticky name-col">参赛者</th><th>{{ detail.contest.scoring_rule === 'ioi' ? '总分' : '通过 / 罚时' }}</th><th v-for="problem in ranking.problems" :key="problem.problem_id">{{problem.label}}<small>{{problem.title}}</small></th></tr></thead><tbody><tr v-for="(row,index) in ranking.rows" :key="row.user_id"><td class="sticky rank-col">{{index+1}}</td><td class="sticky name-col">{{row.name}}</td><td class="total-cell"><strong v-if="detail.contest.scoring_rule==='ioi'">{{row.total_score}}</strong><strong v-else>{{row.solved}}</strong><small v-if="detail.contest.scoring_rule==='acm'">{{row.penalty_minutes}} 分钟</small></td><td v-for="problem in ranking.problems" :key="problem.problem_id"><ContestScoreCell :rule="detail.contest.scoring_rule" :cell="cellFor(row, problem.problem_id)" /></td></tr></tbody></table></div>
          </section>
        </template>
      </main>

      <el-dialog v-model="submitVisible" :title="`提交 ${selectedLink?.label || ''} · ${selectedLink?.problem.title || ''}`" width="min(940px, calc(100vw - 24px))" destroy-on-close><SubmissionComposer ref="composer" v-model:language="language" v-model:source="source" :draft-context="draftContext" :status="liveStatus?.status" :message="liveStatus?.message" :submitting="submitting" scope-text="代码仅计入本场团队比赛" @submit="submitSolution"/><template #footer><el-button @click="submitVisible=false">关闭</el-button></template></el-dialog>
      <el-dialog v-model="addVisible" title="添加比赛题目" width="460px"><p class="muted">输入公共题目或本团队私有题目的题号。</p><el-input v-model="problemCode" placeholder="例如 T001" @keyup.enter="addProblem"/><template #footer><el-button @click="addVisible=false">取消</el-button><el-button type="primary" :loading="adding" @click="addProblem">添加</el-button></template></el-dialog>
      <el-dialog v-model="editVisible" title="比赛设置" width="min(620px, calc(100vw - 24px))"><el-form label-position="top"><el-form-item label="比赛标题"><el-input v-model="editForm.title"/></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="editForm.starts_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="时长（分钟）"><el-input-number v-model="editForm.duration_minutes" :min="15"/></el-form-item><el-form-item label="赛制"><el-segmented v-model="editForm.scoring_rule" :options="scoringOptions"/></el-form-item><el-form-item label="封榜"><el-switch v-model="editForm.freeze_enabled" :disabled="editForm.scoring_rule==='oi'"/><el-input-number v-if="editForm.freeze_enabled" v-model="editForm.freeze_duration_minutes" :min="1" :max="Math.max(1,editForm.duration_minutes-1)"/></el-form-item><el-form-item label="说明"><el-input v-model="editForm.description" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" :loading="editing" @click="saveContest">保存</el-button></template></el-dialog>
    </div>
    <el-skeleton v-else :rows="12" animated class="loading" />
  </section>
</template>

<script setup lang="ts">
import { ElMessage } from 'element-plus'; import { computed,defineComponent,h,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { client,getLatestSubmissions,openEventStream,type AuthenticatedEventSource,type ScoringRule,type Submission } from '../../api/client'; import ProblemStatementView from '../../components/ProblemStatementView.vue'; import StatusBadge from '../../components/StatusBadge.vue'; import SubmissionComposer from '../../components/SubmissionComposer.vue'; import { loadSubmissionDraft } from '../../features/submissions/drafts'; import { formatDateTime } from '../../features/time'; import { useAuthStore } from '../../stores/auth';
const route=useRoute(),router=useRouter(),auth=useAuthStore(); const detail=ref<any>(null),ranking=ref<any>({rows:[],problems:[]}),records=ref<Submission[]>([]),rankingLoading=ref(false),submitVisible=ref(false),submitting=ref(false),language=ref('cpp'),source=ref(''),liveStatus=ref<any>(null),composer=ref<any>(null),addVisible=ref(false),adding=ref(false),problemCode=ref(''),editVisible=ref(false),editing=ref(false),publishing=ref(false); let stream:AuthenticatedEventSource|null=null
const scoringOptions=[{label:'OI',value:'oi'},{label:'IOI',value:'ioi'},{label:'ACM',value:'acm'}]; const editForm=reactive({title:'',description:'',starts_at:'',duration_minutes:120,scoring_rule:'acm' as ScoringRule,freeze_enabled:false,freeze_duration_minutes:60,gold_award_percent:10,silver_award_percent:10,bronze_award_percent:10}); const contestID=computed(()=>Number(route.params.contestId)); const section=computed(()=>route.name==='contest-description'?'description':route.name==='contest-problems'?'problems':route.name==='contest-problem'?'problem':'scoreboard'); const selectedLink=computed(()=>detail.value?.problems?.find((i:any)=>String(i.label).toLowerCase()===String(route.params.label||'').toLowerCase())||null); const problemRecords=computed(()=>records.value.filter(i=>i.problem_id===selectedLink.value?.problem_id)); const draftContext=computed(()=>({userId:auth.user?.id||0,resourceType:'contest' as const,resourceId:contestID.value,problemId:selectedLink.value?.problem_id||0}));
async function loadDetail(){try{detail.value=(await client.get(`/contests/${contestID.value}`)).data;if(detail.value.contest.scoring_rule==='oi'&&section.value==='scoreboard')await router.replace(`/contest/${contestID.value}/problems`);Object.assign(editForm,{...detail.value.contest});if(route.query.manage==='edit'&&detail.value.can_edit){editVisible.value=true;await router.replace({path:route.path,query:{}})}await loadRecords()}catch(e:any){ElMessage.error(e.response?.data?.error||e.message);await router.replace('/teams')}} async function loadRecords(){if(!contestID.value)return;try{records.value=(await client.get(`/contests/${contestID.value}/submissions`)).data||[]}catch{records.value=[]}} async function loadRanking(){if(detail.value?.contest.scoring_rule==='oi')return;rankingLoading.value=true;try{ranking.value=(await client.get(`/contests/${contestID.value}/ranking`)).data||{rows:[],problems:[]}}catch(e:any){ElMessage.error(e.response?.data?.error||e.message)}finally{rankingLoading.value=false}}
function problemRoute(link:any){return `/contest/${contestID.value}/problems/${encodeURIComponent(link.label)}`} function goBack(){void router.push(detail.value?.team?.slug?`/teams/${detail.value.team.slug}/contests`:'/teams')} function dateText(v?:string){return v?formatDateTime(v):'待定'} function shortTime(v:string){return new Date(v).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})} function scoringLabel(v:ScoringRule){return v.toUpperCase()} function scoringDescription(v:ScoringRule){return v==='oi'?'最后一次提交计分，结束前隐藏结果':v==='ioi'?'每题最高得分，总分优先':'通过题数优先，错误提交计入罚时'} function statusLabel(v:string){return v==='draft'?'草稿':v==='published'?'待开始':v==='running'?'进行中':'已结束'} function problemStatusLabel(v?:string){return !v?'未提交':v==='recorded'?'已记录':v==='accepted'?'已通过':['queued','running'].includes(v)?'评测中':'已提交'} function problemStatusType(v?:string):'success'|'warning'|'info'{return v==='accepted'?'success':v?'warning':'info'} function cellFor(row:any,id:number){return row.problems?.find((i:any)=>i.problem_id===id)||{}}
async function openSubmit(){if(!selectedLink.value)return;const latest=(await getLatestSubmissions({team_contest_id:contestID.value},selectedLink.value.problem_id))[0];language.value=latest?.language||'cpp';source.value=loadSubmissionDraft(draftContext.value,language.value)??latest?.source_code??'';liveStatus.value=latest||null;submitVisible.value=true} async function submitSolution(){if(!source.value.trim())return ElMessage.warning('请输入代码');submitting.value=true;try{const {data}=await client.post(`/contests/${contestID.value}/submissions`,{problem_id:selectedLink.value.problem_id,language:language.value,source_code:source.value});composer.value?.clearDraft();liveStatus.value=data;stream?.close();stream=openEventStream(`/submissions/${data.id}/events`);stream.addEventListener('status',async (event:MessageEvent<string>)=>{liveStatus.value=JSON.parse(event.data);if(!['queued','running'].includes(liveStatus.value.status)){stream?.close();stream=null;await Promise.all([loadDetail(),loadRanking()])}});ElMessage.success('代码已提交')}catch(e:any){ElMessage.error(e.response?.data?.error||e.message)}finally{submitting.value=false}}
async function addProblem(){if(!problemCode.value.trim())return;adding.value=true;try{await client.post(`/contests/${contestID.value}/problems`,{problem_code:problemCode.value.trim()});problemCode.value='';addVisible.value=false;await loadDetail();ElMessage.success('题目已加入比赛')}catch(e:any){ElMessage.error(e.response?.data?.error||e.message)}finally{adding.value=false}} async function saveContest(){if(editForm.scoring_rule==='oi')editForm.freeze_enabled=false;editing.value=true;try{await client.put(`/contests/${contestID.value}`,editForm);editVisible.value=false;await loadDetail();ElMessage.success('设置已保存')}catch(e:any){ElMessage.error(e.response?.data?.error||e.message)}finally{editing.value=false}} async function publishContest(){publishing.value=true;try{await client.post(`/contests/${contestID.value}/publish`);await loadDetail();ElMessage.success('比赛已发布')}catch(e:any){ElMessage.error(e.response?.data?.error||e.message)}finally{publishing.value=false}}
const ContestScoreCell=defineComponent({props:{rule:{type:String,required:true},cell:{type:Object,required:true}},setup(p){return()=>{const c:any=p.cell;if(!c.attempts&&!c.best_score)return h('span',{class:'cell-empty'},'未提交');if(p.rule==='ioi')return h('div',{class:'score-cell'},[h('strong',String(c.best_score||0)),h('small',c.elapsed_minutes?`${c.elapsed_minutes} 分钟`:'')]);const accepted=c.solved_at||c.status==='accepted';return h('div',{class:['score-cell',accepted?'accepted':'wrong']},[h('strong',accepted?'AC':`WA × ${c.wrong_attempts||c.attempts}`),h('small',accepted?`${c.elapsed_minutes} 分钟`:`${c.attempts} 次`)])}}})
watch(()=>route.fullPath,async()=>{if(!detail.value||Number(route.params.contestId)!==detail.value.contest.id)await loadDetail();if(section.value==='scoreboard')await loadRanking()}); onMounted(async()=>{await loadDetail();if(section.value==='scoreboard')await loadRanking()});onBeforeUnmount(()=>stream?.close())
</script>

<style scoped>
