rap,.scoreboard-scroll{overflow:auto}.problem-table,.scoreboard{width:100%;border-collapse:collapse}.problem-table{margin-top:16px}.problem-table th,.problem-table td{padding:14px 16px;text-align:left;border-bottom:1px solid var(--border)}.problem-table th{color:var(--muted);font-size:12px;background:color-mix(in srgb,var(--surface) 88%,#e9eff5)}.problem-table a{color:var(--text);font-weight:700}.problem-table td:first-child a{color:var(--accent)}.problem-toolbar{padding-bottom:14px;border-bottom:1px solid var(--border)}.problem-toolbar>div span,.problem-toolbar>div strong{display:block}.problem-toolbar>div span{color:var(--accent);font-weight:800}.problem-toolbar>div strong{margin-top:4px;font-size:19px}.problem-side{display:grid;align-content:start;gap:12px}.navigator h3,.records h3{margin:0}.navigator>div{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}.navigator a{min-width:38px;padding:8px;text-align:center;border:1px solid var(--border);border-radius:6px}.navigator a.active{color:#fff;border-color:var(--accent);background:var(--accent)}.records article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:8px;padding:10px 0;border-bottom:1px solid var(--border)}.records time{color:var(--muted);font-size:12px}.scoreboard-panel .el-alert{margin-top:14px}.scoreboard-scroll{margin-top:16px;border:1px solid var(--border);border-radius:7px}.scoreboard{min-width:760px}.scoreboard th,.scoreboard td{min-width:108px;padding:11px 12px;text-align:center;border-right:1px solid var(--border);border-bottom:1px solid var(--border);background:var(--surface-strong)}.scoreboard th{color:var(--muted);font-size:12px;background:#f3f6f9}.scoreboard th small{display:block;max-width:110px;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.scoreboard .sticky{position:sticky;z-index:2}.rank-col{left:0;min-width:66px!important}.name-col{left:66px;min-width:150px!important;text-align:left!important}.scoreboard tbody .name-col{font-weight:700}.total-cell strong,.total-cell small,.score-cell strong,.score-cell small{display:block}.total-cell strong{font-size:18px}.total-cell small,.score-cell small{color:var(--muted);font-size:11px}.score-cell.accepted strong{color:#159447}.score-cell.wrong strong{color:#d55454}.cell-empty{color:#a7b0bc}.muted{color:var(--muted)}.loading{width:min(1180px,100%);margin:20px auto}@media(max-width:800px){.contest-page{padding:16px 12px 42px}.contest-title-row,.section-heading,.problem-toolbar{align-items:stretch;flex-direction:column}.contest-stats{width:100%}.contest-stats article{flex:1}.two-column,.problem-layout{grid-template-columns:1fr}.problem-side{order:-1}.contest-nav a{padding:12px 14px}.description-panel,.meta-panel,.problem-list-panel,.statement-panel,.navigator,.records,.scoreboard-panel{padding:15px}}
</style>
